        nums = {'one':1,'two':2,'three':3,'four':4,'five':5,'six':6,'seven':7,'eight':8,'nine':9,'ten':10}
        m = re.match(r'(one|two|three|four|five|six|seven|eight|nine|ten)\s+(.+)', phrase)
        if m:
            return nums[m.group(1)], m.group(2).strip()
        return 1, phrase

    def base_name(name):
        return re.sub(r'\s+\d+$', '', name).strip()

    def parse_goal(g):
        g = g.lower()
        m = re.search(r'put\s+(.+?)\s+(?:in|into|on|to)\s+(.+?)(?:\.|$)', g)
        if m:
            return m.group(1).strip(), m.group(2).strip()
        return None, None

    target_phrase, dest_phrase = parse_goal(goal)
    if target_phrase is None:
        return
    num, target = count_needed(target_phrase)
    target = base_name(target)
    dest = base_name(dest_phrase)

    obs = env.observation
    receptacles = []
    for m in re.finditer(r'\b([a-z]+ \d+)\b', obs):
        name = m.group(1)
        if name not in receptacles:
            receptacles.append(name)

    state = {'steps': 0, 'current': None, 'carrying': None, 'delivered': 0, 'candidates': []}

    def step(cmd):
        if state['steps'] >= 49:
            return None
        state['steps'] += 1
        return env.step(cmd)

    def go(name):
        if state['steps'] >= 49:
            return None
        r = step("go to " + name)
        if r is None:
            return None
        if 'nothing happens' in r.lower() or 'you arrive' not in r.lower():
            # invalid destination; don't update current
            return r
        state['current'] = name
        return r

    def scan(rec):
        r = go(rec)
        if r is None:
            return None
        # if drawers closed, try open
        if 'closed' in r.lower():
            step("open " + rec)
            r2 = step("look")
            return r2
        return r

    def find_targets_in(text):
        return re.findall(r'\b' + re.escape(target) + r' \d+\b', text)

    # Initial scan to find candidates
    for rec in receptacles:
        if state['steps'] >= 40:
            break
        r = scan(rec)
        if r is None:
            break
        found = find_targets_in(r)
        for f in found:
            state['candidates'].append((rec, f))

    # Check inventory
    if state['steps'] < 48:
        inv = step("inventory")
        if inv:
            held = find_targets_in(inv)
            if held:
                state['carrying'] = held[0]

    def pick_from(rec, obj):
        r = go(rec)
        if r is None:
            return False
        # verify object still present
        r2 = step("look")
        if r2 and obj in r2:
            rr = step("take " + obj + " from " + rec)
            if rr and ('pick up' in rr.lower() or 'you pick' in rr.lower()):
                state['carrying'] = obj
                return True
        return False

    def drop_at_dest():
        if state['carrying'] is None:
            return False
        r = go(dest)
        if r is None:
            return False
        rr = step("move " + state['carrying'] + " to " + dest)
        if rr and 'you move' in rr.lower():
            state['carrying'] = None
            state['delivered'] += 1
            return True
        return False

    # Delivery loop
    while state['delivered'] < num and state['steps'] < 48:
        if state['carrying'] is None:
            picked = False
            # try candidates
            for rec, obj in list(state['candidates']):
                if state['steps'] >= 48:
                    break
                if pick_from(rec, obj):
                    state['candidates'].remove((rec, obj))
                    picked = True
                    break
            if not picked:
                # rescan all receptacles
                for rec in receptacles:
                    if state['steps'] >= 48:
                        break
                    r = scan(rec)
                    if r is None:
                        break
                    found = find_targets_in(r)
                    for f in found:
                        if state['steps'] >= 48:
                            break
                        if pick_from(rec, f):
                            picked = True
                            break
                    if picked:
                        break
            if not picked:
                # check inventory one more time
                inv = step("inventory")
                if inv:
                    held = find_targets_in(inv)
                    if held:
                        state['carrying'] = held[0]
                        continue
                break
        drop_at_dest()

    if state['carrying'] is not None and state['steps'] < 49:
        drop_at_dest()
